def process(cleanIdentityTheftStateMsa):
    import pandas as pd

    # Cross-state MSAs appear in multiple state files; sum unique MSAs once.
    grp = (
        cleanIdentityTheftStateMsa
        .groupby('metropolitan_area', as_index=False)
        .agg(reports=('reports', 'max'))
    )

    total = int(grp['reports'].sum())
    return pd.DataFrame([{'total_reports_2024_cross_state_msa': total}])
